{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Bumetanide, a close sulfamoylbenzoic acid loop diuretic analogue, showed 80% absolute oral bioavailability in normal subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Metoclopramide in patients with cirrhosis had absolute oral bioavailability 79.0 ± 18.8%, indicating that cirrhosis does not inherently lower F below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tolfenamic acid in patients with alcoholic cirrhosis showed about 100% oral bioavailability, providing condition-matched evidence for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Azosemide, a structurally similar sulfamoylbenzoic acid diuretic with a tetrazole acid bioisostere, had absolute oral bioavailability about 20.4%, near the threshold and contradictory to high F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence from close analogues (bumetanide, metoclopramide in cirrhosis, tolfenamic acid in cirrhosis) supports F >= 20%; azosemide's borderline low value and the physicochemical prior create uncertainty, but the class majority and condition-matched data favor high.",
  "evidence_gaps": [
    "No direct furosemide bioavailability measurement in cirrhosis was supplied.",
    "Azosemide low bioavailability conflicts with bumetanide high bioavailability, leaving class uncertainty.",
    "Cirrhosis-specific data for loop diuretics are limited to indirect analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

